using namespace std;

#include <iostream>
#include <vector>

class SubsetSum {
 public:
  static int countSubsets(const vector<int> &num, int sum) {
    int n = num.size();
    vector<int> dp(sum + 1);
    dp[0] = 1;

    // with only one number, we can form a subset only when the required sum is
